const prizes=['Giải khuyến khích','Giải ba','Giải nhì','Giải nhất','Giải đặc biệt'];
const symbols=['✧','③','②','①','♛'];
let length=4, rangeMin=1, rangeMax=3144, quotas=[3,1,1,1,1], results=prizes.map(()=>[]), amounts=[100000,200000,300000,500000,1000000], busy=false, landing=null, fresh=null, pending=null, lastScreen='draw';
const $=id=>document.getElementById(id);
const total=()=>quotas.reduce((a,b)=>a+b,0);
const done=()=>results.reduce((a,b)=>a+b.length,0);
const current=()=>prizes.findIndex((_,i)=>results[i].length<quotas[i]);
const prizeName=(i,k)=>quotas[i]>1?`${prizes[i]} ${k+1}`:prizes[i];
const numberLabel=(i,k)=>{const s=prizeName(i,k).replace('Giải ','');return s[0].toUpperCase()+s.slice(1)};
const STORE='ve-so-yeu-thuong-2026';
function save(){try{localStorage.setItem(STORE,JSON.stringify({v:1,length,rangeMin,rangeMax,quotas,amounts,results,pending,lastScreen}))}catch{}}
function load(){try{const d=JSON.parse(localStorage.getItem(STORE));if(!d||d.v!==1||d.quotas?.length!==prizes.length||d.results?.length!==prizes.length||d.amounts?.length!==prizes.length)return;({length,rangeMin,rangeMax,quotas,amounts,results,pending,lastScreen}=d)}catch{}}
const money=v=>v==null?'':v.toLocaleString('vi-VN')+' VNĐ';
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function makeDigits(){ $('digits').replaceChildren(...Array.from({length},()=>{const el=document.createElement('div');el.className='digit';el.textContent='0';return el})); }
function render(){const p=current();$('count').textContent=done()+' số';$('results').innerHTML=prizes.map((name,i)=>`<div class="result-group ${i===p?'active':''}"><div class="result-head"><span class="symbol">${symbols[i]}</span>${name}<small>${results[i].length}/${quotas[i]}</small></div>${amounts[i]==null?'':`<div class="result-amount">${money(amounts[i])}</div>`}<div class="result-numbers">${results[i].map((n,k)=>{const chip=`<span class="winner${n===landing?' landing':''}${n===fresh?' fresh':''}" data-number="${n}">26-${n}</span>`;return quotas[i]>1?`<span class="winner-item"><small>${numberLabel(i,k)}</small>${chip}</span>`:chip}).join('')}</div></div>`).join('');$('progress-text').textContent=`${done()} / ${total()} lượt`;$('progress-fill').style.width=100*done()/total()+'%';$('steps').innerHTML=prizes.map((n,i)=>`<span class="${i===p?'current':''}">${n.replace('Giải ','')}</span>`).join('');$('format-label').textContent=`${length} chữ số · ${String(rangeMin).padStart(length,'0')}–${String(rangeMax).padStart(length,'0')}`;$('spin').disabled=busy;$('settings').disabled=busy;save()}
function ready(){const p=current();if(p<0){$('spin').textContent='✦  KẾT THÚC';$('next').textContent='Đã trao tất cả giải. Bấm Kết thúc để xem bảng tổng kết.';return}$('prize-symbol').textContent=symbols[p];$('prize').textContent=prizeName(p,results[p].length);$('prize-amount').textContent=money(amounts[p]);$('prize-amount').hidden=amounts[p]==null;$('round').textContent=`Lượt ${results[p].length+1} / ${quotas[p]} của giải · ${length} chữ số`;$('next').textContent=`${total()-done()} lượt quay đang chờ`;}
function randomNumber(max){const a=new Uint32Array(1),limit=4294967296-4294967296%max;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%max;}
function pick(){const used=new Set(results.flat().map(Number));const available=[];for(let n=rangeMin;n<=rangeMax;n++)if(!used.has(n))available.push(n);if(!available.length)throw new Error('Không còn số để quay');return String(available[randomNumber(available.length)]).padStart(length,'0');}
function validateRange(from,to,digitCount,drawCount){if(!/^\d+$/.test(from)||!/^\d+$/.test(to))return 'Vui lòng nhập số nguyên không âm cho khoảng quay.';const min=Number(from),max=Number(to);if(!Number.isSafeInteger(min)||!Number.isSafeInteger(max)||min>max||max>=10**digitCount)return `Khoảng quay phải từ ${'0'.repeat(digitCount)} đến ${'9'.repeat(digitCount)}, và Từ số không lớn hơn Đến số.`;if(drawCount>max-min+1)return `Khoảng này chỉ có ${max-min+1} số. Hãy giảm tổng lượt quay hoặc mở rộng khoảng quay.`;return '';}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
let audio=null,soundOn=true;
function audioCtx(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}
function tone(freq,start,dur,type,vol){const a=audioCtx(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(vol,start+.01);g.gain.exponentialRampToValueAtTime(.001,start+dur);o.connect(g).connect(a.destination);o.start(start);o.stop(start+dur+.05)}
const music=new Audio('nhac-xo-so.mp3'),quiet=.3,loud=1;music.loop=true;music.preload='auto';music.volume=quiet;let fade=null;
function musicVolume(target,ms=700){clearInterval(fade);const from=music.volume,t0=performance.now();fade=setInterval(()=>{const k=Math.min(1,(performance.now()-t0)/ms);music.volume=from+(target-from)*k;if(k===1)clearInterval(fade)},30)}
function chime(){if(!soundOn)return;const t=audioCtx().currentTime;tone(1319,t,.5,'sine',.25);tone(1976,t+.06,.4,'sine',.12)}
function fanfare(){if(!soundOn)return;const t=audioCtx().currentTime;[523,659,784,1047].forEach((f,i)=>tone(f,t+i*.13,i===3?1.2:.3,'triangle',.22));tone(1568,t+.52,1.2,'sine',.1)}
function celebrate(box=$('confetti')){if(reducedMotion())return;const pieces=Array.from({length:65},(_,i)=>{const el=document.createElement('i');el.style.left=Math.random()*100+'%';el.style.background=['#edbf65','#fff0bd','#ef7772'][i%3];el.style.animationDelay=Math.random()*.5+'s';return el});box.replaceChildren(...pieces);setTimeout(()=>box.replaceChildren(),3500)}
function flip(el,from,duration){const to=el.getBoundingClientRect();if(reducedMotion()||!to.width)return Promise.resolve();const dx=from.left+from.width/2-to.left-to.width/2,dy=from.top+from.height/2-to.top-to.height/2;return el.animate([{transform:`translate(${dx}px,${dy}px) scale(${from.width/to.width})`},{transform:'none'}],{duration,easing:'cubic-bezier(.2,.75,.2,1)'}).finished}
function congratulate(p,number){const d=$('congrats');$('congrats-symbol').textContent=symbols[p];$('congrats-prize').textContent=prizeName(p,results[p].length);$('congrats-amount').textContent=money(amounts[p]);$('congrats-amount').hidden=amounts[p]==null;$('congrats-number').textContent='26-'+number;const a=document.querySelector('.ticket-prefix').getBoundingClientRect(),b=$('digits').getBoundingClientRect(),from=new DOMRect(a.left,Math.min(a.top,b.top),b.right-a.left,Math.max(a.bottom,b.bottom)-Math.min(a.top,b.top));d.showModal();flip($('congrats-number'),from,900);celebrate($('congrats-confetti'));const btn=$('congrats-next');let left=10;btn.textContent=`Tiếp tục (${left}s) →`;return new Promise(resolve=>{const stop=new AbortController(),tick=setInterval(()=>{left--;btn.textContent=`Tiếp tục (${left}s) →`;if(left<=0)next()},1000),next=e=>{e?.preventDefault();clearInterval(tick);stop.abort();resolve()};$('congrats-next').addEventListener('click',next,{signal:stop.signal});d.addEventListener('cancel',next,{signal:stop.signal})})}
async function flyToBoard(number){const big=$('congrats-number'),from=big.getBoundingClientRect();landing=number;render();$('congrats').close();const chip=$('results').querySelector(`[data-number="${number}"]`);let to=chip.getBoundingClientRect();if(to.bottom<0||to.top>innerHeight){chip.scrollIntoView({block:'center'});to=chip.getBoundingClientRect()}if(!reducedMotion()){const ghost=big.cloneNode(true);ghost.removeAttribute('id');ghost.classList.add('flying');Object.assign(ghost.style,{left:from.left+'px',top:from.top+'px',width:from.width+'px',height:from.height+'px'});document.body.append(ghost);const k=to.width/from.width;await Promise.race([ghost.animate([{transform:'none'},{transform:`translate(${to.left-from.left}px,${to.top+to.height/2-from.top-from.height*k/2}px) scale(${k})`}],{duration:1300,easing:'cubic-bezier(.45,0,.2,1)'}).finished,delay(1500)]);ghost.remove()}landing=null;fresh=number}
async function spin(){if(busy||current()<0)return;busy=true;fresh=null;ready();const p=current(),number=pending?.p===p?pending.number:pick();pending={p,number};$('announcement').textContent='';$('hint').textContent='May mắn đang được hé lộ…';$('spin').textContent='ĐANG QUAY…';render();const cells=[...$('digits').children];cells.forEach(c=>c.className='digit rolling');let remaining=length;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;musicVolume(loud);const ticker=setInterval(()=>cells.forEach((c,i)=>{if(i<remaining)c.textContent=reduced?'·':Math.floor(Math.random()*10)}),70);try{await delay(1800);for(let i=length-1;i>=0;i--){remaining=i;cells[i].textContent=number[i];cells[i].className='digit locked';chime();await delay(i===0?600:5000)}musicVolume(quiet);clearInterval(ticker);$('announcement').textContent=`Chúc mừng vé 26-${number}!`;$('hint').textContent=`Đã tìm thấy chủ nhân ${prizeName(p,results[p].length).toLowerCase()}`;fanfare();await congratulate(p,number);makeDigits();$('announcement').textContent='';$('hint').textContent='Hé lộ từng chữ số từ phải sang trái ←';results[p].push(number);pending=null;await flyToBoard(number)}finally{musicVolume(quiet);clearInterval(ticker);landing=null;busy=false;render();ready();$('spin').textContent=current()<0?'✦  KẾT THÚC':'✦  QUAY LƯỢT TIẾP THEO';$('next').textContent=current()<0?'Đã trao tất cả giải. Bấm Kết thúc để xem bảng tổng kết.':`Tiếp theo: ${prizeName(current(),results[current()].length)}`;}}
const show=screen=>{document.body.dataset.screen=screen;if(screen!=='welcome')lastScreen=screen;save();scrollTo(0,0)};
function resetProgram(){results=prizes.map(()=>[]);fresh=null;pending=null;lastScreen='draw';makeDigits();render();ready();$('announcement').textContent='';$('hint').textContent='Hé lộ từng chữ số từ phải sang trái ←';$('spin').textContent='✦  QUAY MAY MẮN'}
function renderFinal(){$('final-grid').innerHTML=prizes.map((name,i)=>quotas[i]?`<div class="final-card${i===prizes.length-1?' special':''}${quotas[i]>1?' multi':''}"><div class="final-head"><span aria-hidden="true">${symbols[i]}</span>${name}</div>${amounts[i]==null?'':`<p class="final-amount">${money(amounts[i])}</p>`}<div class="final-numbers">${results[i].map((n,k)=>`<div class="final-item">${quotas[i]>1?`<small>${numberLabel(i,k)}</small>`:''}<span class="num">26-${n}</span></div>`).join('')}</div></div>`:'').reverse().join('')}
function finish(){renderFinal();show('final');celebrate()}
$('start').addEventListener('click',()=>{music.muted=!soundOn;music.volume=quiet;music.play().catch(()=>{});if(lastScreen==='final'&&current()<0){renderFinal();show('final')}else show('draw')});
$('spin').addEventListener('click',()=>{if(busy)return;current()<0?finish():spin()});
$('restart').addEventListener('click',()=>{if(busy||!confirm('Bắt đầu chương trình mới? Kết quả hiện tại sẽ bị xóa.'))return;resetProgram();show('draw')});
function setButton(btn,icon,label){btn.firstChild.textContent=icon;btn.lastChild.textContent=label;btn.title=label}
$('sound').addEventListener('click',()=>{soundOn=!soundOn;music.muted=!soundOn;setButton($('sound'),soundOn?'🔊':'🔇',soundOn?'Âm thanh':'Tắt tiếng');$('sound').setAttribute('aria-pressed',soundOn)});
if(!document.fullscreenEnabled)$('fullscreen').hidden=true;
$('fullscreen').addEventListener('click',()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{}));
document.addEventListener('fullscreenchange',()=>{const on=!!document.fullscreenElement;setButton($('fullscreen'),on?'🗗':'⛶',on?'Thoát toàn màn hình':'Toàn màn hình')});
$('settings').addEventListener('click',()=>{if(busy)return;document.querySelector(`input[name="length"][value="${length}"]`).checked=true;$('range-min').value=String(rangeMin).padStart(length,'0');$('range-max').value=String(rangeMax).padStart(length,'0');$('quotas').innerHTML=prizes.map((n,i)=>`<div class="quota-row"><span>${n}</span><input class="amount" aria-label="Số tiền ${n}" type="text" inputmode="numeric" placeholder="Không ghi" value="${amounts[i]==null?'':amounts[i].toLocaleString('vi-VN')}"><input class="quota" aria-label="Số lượt ${n}" type="number" min="0" max="1000" step="1" required value="${quotas[i]}"></div>`).join('');$('reset-note').hidden=done()===0;$('config-error').textContent='';$('config').showModal()});
$('close').addEventListener('click',()=>$('config').close());
$('config-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;const rows=[...$('quotas').querySelectorAll('.quota-row')],q=rows.map(r=>Number(r.querySelector('.quota').value));if(q.some(n=>!Number.isInteger(n)||n<0||n>1000)||q.reduce((a,b)=>a+b,0)===0){$('config-error').textContent='Hãy đặt ít nhất 1 lượt quay. Mỗi giải từ 0 đến 1.000 lượt.';return}const selectedLength=Number(document.querySelector('input[name="length"]:checked').value),from=$('range-min').value.trim(),to=$('range-max').value.trim();const error=validateRange(from,to,selectedLength,q.reduce((a,b)=>a+b,0));if(error){$('config-error').textContent=error;return}const rawAmounts=rows.map(r=>r.querySelector('.amount').value.replace(/[.,\s]|vn[dđ]|đ/gi,''));if(rawAmounts.some(v=>!/^\d{0,13}$/.test(v))){$('config-error').textContent='Số tiền chỉ gồm chữ số, ví dụ 500000 hoặc 500.000. Để trống nếu không muốn hiển thị.';return}amounts=rawAmounts.map(v=>v===''?null:Number(v));if(selectedLength===length&&Number(from)===rangeMin&&Number(to)===rangeMax&&q.every((n,i)=>n===quotas[i])){render();ready();renderFinal();$('config').close();return}length=selectedLength;rangeMin=Number(from);rangeMax=Number(to);quotas=q;resetProgram();if(document.body.dataset.screen==='final')show('draw');$('config').close()});
load();makeDigits();render();ready();if(done()||pending){$('start').lastChild.textContent=' TIẾP TỤC';$('resume-note').textContent=`Đã khôi phục ${done()} số đã quay. Bấm Tiếp tục để quay tiếp.`;$('resume-note').hidden=false}




